    "definitions": [
      {
        "name": "Approval rate",
        "text": "Approval rate is the share of decided cases whose final outcome is approved. The denominator is cases with a final outcome of approved or denied. Pending and abandoned cases are excluded. An appeal that is approved counts as approved. A plan exclusion denial is a decision."
      },
      {
        "name": "First pass approval rate",
        "text": "First pass approval rate is the share of decided cases that were approved on the initial decision, with no information request and no appeal. The denominator is the same decided set as the approval rate."
      },
      {
        "name": "Median hours to decision",
        "text": "Median hours to decision is the median calendar hours from prior authorization submission to the effective initial decision. Cases with no submission are excluded. The median ignores nulls. Calendar hours are used because the Medicare drug clocks are calendar time."
      },
      {
        "name": "Abandonment rate",
        "text": "Abandonment rate is abandoned cases divided by cases that reached a prior authorization requirement and then closed as abandoned, approved, or denied."
      },
      {
        "name": "Appeal overturn rate",
        "text": "Appeal overturn rate is appeal decisions that are approvals, divided by cases with an appeal decision."
      },
      {
        "name": "Time to therapy",
        "text": "Time to therapy is the median calendar hours from the benefit check start to approval, on approved cases only. It is a proxy for access approval. It is not a pharmacy fill."
      },
      {
        "name": "Cases stuck",
        "text": "A case is stuck when it is still open and the hours in the current stage are greater than the stage SLA. A case at exactly the SLA is not stuck. The as of time is 2026-11-02 00:00:00, not the clock on the machine."
      },
      {
        "name": "Case count",
        "text": "Case count is the number of cases in the slice after QA fixtures are removed."
      }
    ],
